flowchart LR
  Start@{ shape: sm-circ } --> Spec@{ shape: doc, label: "Intake Spec" }
  Spec --> Batch@{ shape: docs, label: "Doc Batch" }
  Batch --> Queue@{ shape: delay, label: "Rate Limit" }
  Batch --> Extract@{ shape: tri, label: "Extract" }
  Queue --> Join@{ shape: f-circ }
  Extract --> Notify@{ shape: flag, label: "Emit Alert" }
  Notify --> Join
  Join --> Out["`**Verified** _Output_`"]
  Join -.-> Note@{ shape: text, label: "Audit Ready" }

classDiagram
  namespace Commerce {
    class Payable {
      <<interface>>
      +pay(amount Decimal) bool*
    }
    class Order {
      +UUID id
      -OrderStatus status
      +create()$ Order
      +total() Decimal
    }
    class OrderItem {
      +String sku
      +int qty
      +Decimal price
    }
  }
  class PaymentService {
    <<service>>
    +pay(amount Decimal) bool
    +refund(orderId UUID) void
  }
  Payable <|.. PaymentService : implements
  Order "1" *-- "1..*" OrderItem : contains
  Order ..> PaymentService : uses
  note for Order "Aggregate root"

erDiagram
  CUSTOMER["Customer"] {
    uuid id PK
    varchar email UK "unique login"
    varchar name
  }
  ORDER {
    uuid id PK
    uuid customer_id FK
    decimal total
    varchar status
  }
  ORDER_ITEM {
    uuid order_id PK,FK
    uuid product_id PK,FK
    int quantity
  }
  PRODUCT {
    uuid id PK
    varchar sku UK
    decimal unit_price
  }
  CUSTOMER ||--o{ ORDER : places
  ORDER ||--|{ ORDER_ITEM : contains
  PRODUCT ||--o{ ORDER_ITEM : "referenced by"
